  dodo_egg: { name: "Dodo egg", stack: 10, desc: "A huge egg from where the dodos live. Fry it on the fire for a big meal.", food: { hunger: 8, sick: 0.2 }, cook: "dodo_egg_cooked", cookVerb: "Fry" },
  dodo_egg_cooked: { name: "Fried dodo egg", stack: 10, desc: "Enough for two. Or one very hungry castaway. Gives you a lift too.", food: { hunger: 40, stamina: 20 } },
  shell_sea: { name: "Shell of sea water", stack: 6, desc: "Too salty to drink. Boil it on a campfire.", cook: "shell_water", cookVerb: "Boil" },
