  torch: { name: "Torch", stack: 20, desc: "Light for the night. Burns while you hold it. Down a mine it lights the way from your bag, so you can dig. Crabs hate it.", tool: { kind: "torch", dmg: 7 }, dur: 300 },
  club: { name: "Palm club", desc: "Heavy and simple. Knocks things back, and a swing can catch up to three at once.", tool: { kind: "club", dmg: 18, knock: 1.4 }, dur: 80, weapon: true },
