  obsidian_sword: { name: "Obsidian sword", desc: "A hardwood blade lined with obsidian teeth. One wide swing cuts through a whole row of crabs.", tool: { kind: "sword", dmg: 34, reach: 2.6, hits: 4, speed: 1.05 }, dur: 170, weapon: true },
  cutlass: { name: "Iron cutlass", desc: "A curved ship\u2019s sword forged from galleon iron. Fast, wide slashes that cut down everything in front of you.", tool: { kind: "sword", dmg: 48, reach: 2.8, hits: 5, speed: 1.2 }, dur: 280, weapon: true },
  machete: { name: "Machete", desc: "Galleon iron beaten into a long blade. Fast, nasty, and it cuts palms and bamboo in no time.", tool: { kind: "knife", chop: 1.7, mine: 0.8, dmg: 24, speed: 1.3 }, dur: 160, weapon: true },
