  iron_spear: { name: "Iron spear", desc: "A forged iron point on a long shaft.", tool: { kind: "spear", dmg: 46, reach: 3.3 }, dur: 240, weapon: true },
  rod: { name: "Fishing rod", desc: "Face some water and use it to cast. When the float bobs under, use it again to reel in.", tool: { kind: "rod", dmg: 3 }, dur: 120 },
