function toolStats(slot) {
  const def = ITEMS[slot.id];
  const t = def.tool || {};
  const L2 = slot.lvl || 1;
  const st = {
    dmg: (t.dmg || 0) * (1 + 0.1 * (L2 - 1)),
    chop: (t.chop || 0) * (1 + 0.1 * (L2 - 1)),
    mine: (t.mine || 0) * (1 + 0.1 * (L2 - 1)),
    knock: t.knock || 0,
    reach: t.reach || 0,
    speed: t.speed || 1,
    heal: 0,
    dur: Math.round((def.dur || 0) * (1 + 0.15 * (L2 - 1)))
  };
  for (const a of slot.att || []) {
    const A = ATTACH[a];
    if (!A) continue;
    st.dmg += A.dmg || 0;
    st.dur += A.dur || 0;
    st.knock += A.knock || 0;
    st.speed += A.speed || 0;
    st.heal += A.heal || 0;
    if (st.reach || A.reach) st.reach = (st.reach || 2) + (A.reach || 0);
    if (st.chop) st.chop += A.chop || 0;
    if (st.mine) st.mine += A.mine || 0;
  }
  st.dmg = Math.round(st.dmg);
  return st;
}
