  const n = g.attributes.position.count;
  const a = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    a[i * 3] = col2.r;
    a[i * 3 + 1] = col2.g;
    a[i * 3 + 2] = col2.b;
  }
