function hideGeo() {
  const g = new PlaneGeometry(0.34, 0.26, 5, 4).rotateX(-Math.PI / 2);
  const p = g.attributes.position;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), z = p.getZ(i);
    p.setY(i, Math.sin(x * 20) * 0.01 + Math.cos(z * 17) * 0.012);
    if (Math.abs(x) > 0.15 || Math.abs(z) > 0.11) {
      p.setX(i, x * (0.85 + Math.sin(i * 3.1) * 0.08));
      p.setZ(i, z * (0.85 + Math.cos(i * 2.3) * 0.08));
    }
  }
  g.computeVertexNormals();
  return merge([paint(g, "#6b4a33"), paint(g.clone().translate(0, -6e-3, 0).rotateX(Math.PI).translate(0, 0, 0), "#a88a6a")]);
}
