function antlerGeo() {
  const seg = (a, b, r) => {
    const d = new Vector3(b[0] - a[0], b[1] - a[1], b[2] - a[2]);
    const L2 = d.length();
    return new CylinderGeometry(r * 0.75, r, L2, 6).translate(0, L2 / 2, 0).applyQuaternion(new Quaternion().setFromUnitVectors(new Vector3(0, 1, 0), d.normalize())).translate(...a);
  };
  const pts = [[0, 0, 0], [0.06, 0.12, 0], [0.1, 0.25, 0.02], [0.08, 0.38, 0.03]];
  const list = [];
  for (let k = 0; k < 3; k++) list.push(paint(seg(pts[k], pts[k + 1], 0.025 - k * 5e-3), "#dccdb0"));
  for (const k of [1, 2]) list.push(paint(seg(pts[k], [pts[k][0] - 0.08, pts[k][1] + 0.08, pts[k][2]], 0.012), "#d0c0a0"));
  return merge(list);
}
function featherGeo() {
  const g = new BufferGeometry();
  const pos = [];
  const L2 = 0.3;
  for (let i = 0; i < 8; i++) {
    const t0 = i / 8, t1 = (i + 1) / 8;
    const w0 = Math.sin(Math.PI * t0) * 0.05 + 5e-3, w1 = Math.sin(Math.PI * t1) * 0.05 + 5e-3;
    const x0 = t0 * L2 - L2 / 2, x1 = t1 * L2 - L2 / 2;
    pos.push(x0, 0.01, -w0, x1, 0.01, -w1, x0, 0.02, 0, x1, 0.01, -w1, x1, 0.02, 0, x0, 0.02, 0, x0, 0.02, 0, x1, 0.02, 0, x0, 0.01, w0, x1, 0.02, 0, x1, 0.01, w1, x0, 0.01, w0);
  }
  g.setAttribute("position", new Float32BufferAttribute(pos, 3));
  g.computeVertexNormals();
  return merge([paint(g, "#a8acb4"), paint(new CylinderGeometry(4e-3, 4e-3, 0.36, 4).rotateZ(Math.PI / 2).translate(-0.02, 0.022, 0), "#e8e4d8")]);
}
function dodoEggGeo(cooked) {
  if (cooked) return merge([paint(new CylinderGeometry(0.16, 0.17, 0.02, 16).scale(1, 1, 0.85), "#f6f2e6"), paint(new SphereGeometry(0.065, 10, 6, 0, Math.PI * 2, 0, Math.PI / 2).scale(1, 0.6, 1).translate(0.02, 0.01, 0), "#f0a018")]);
  const g = new SphereGeometry(0.078, 18, 14).scale(1, 1.3, 1).translate(0, 0.1, 0);
  const p = g.attributes.position, col2 = [];
  const base = new Color("#ece2c8"), dot = new Color("#a89478"), c = new Color();
  const r = mulberry32(61);
  const dots = Array.from({ length: 22 }, () => [r() * 6.28, 0.03 + r() * 0.15]);
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), y = p.getY(i), z = p.getZ(i);
    const a = Math.atan2(z, x);
    c.copy(base);
    for (const [da, dy] of dots) {
      let d = Math.abs(a - da);
      d = Math.min(d, 6.283 - d);
      if (Math.hypot(d * 0.07, y - dy) < 0.011) {
        c.copy(dot);
        break;
      }
    }
    col2.push(c.r, c.g, c.b);
  }
  g.setAttribute("color", new Float32BufferAttribute(col2, 3));
  g.deleteAttribute("uv");
  return merge([g]);
}
