function pineappleGeo() {
  const g = new SphereGeometry(0.075, 12, 10).scale(1, 1.4, 1);
  const p = g.attributes.position;
  const col2 = [];
  const a = new Color("#d9a53a"), b = new Color("#8a6a1e");
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), y = p.getY(i), z = p.getZ(i);
    const ang = Math.atan2(z, x);
    const d = Math.sin(ang * 6 + y * 60) * Math.sin(ang * 6 - y * 60);
    const c = a.clone().lerp(b, d > 0.35 ? 0.8 : 0);
    col2.push(c.r, c.g, c.b);
  }
  g.setAttribute("color", new Float32BufferAttribute(col2, 3));
  g.deleteAttribute("uv");
  const list = [nonIndexed(g).translate(0, 0.1, 0)];
  for (let k = 0; k < 9; k++) {
    const an = k / 9 * Math.PI * 2;
    list.push(paint(new ConeGeometry(0.018, 0.13 + k % 3 * 0.02, 4).translate(0, 0.065, 0).rotateZ(0.25 + k % 2 * 0.2).rotateY(an).translate(0, 0.2, 0), k % 2 ? "#4f7f3a" : "#6a9a46"));
  }
  return merge(list);
}
function chilliGeo() {
  const list = [];
  for (let k = 0; k < 3; k++) {
    const n = 5;
    for (let i = 0; i < n; i++) {
      const t = i / n;
      const r = 0.022 * (1 - t * 0.8);
      list.push(paint(new CylinderGeometry(r * 0.8, r, 0.045, 7).rotateZ(Math.PI / 2 + t * 0.9).translate(-0.1 + t * 0.2, Math.sin(t * 2.5) * 0.03 + k * 0.02, (k - 1) * 0.05), k === 1 ? "#c8261e" : "#e03a22"));
    }
    list.push(paint(new CylinderGeometry(6e-3, 8e-3, 0.05, 5).rotateZ(Math.PI / 2).translate(-0.135, k * 0.02, (k - 1) * 0.05), "#4a7a2a"));
  }
  return merge(list);
}
