function renderIcons(size = 96) {
  const icons = {};
  let r;
  try {
    r = new WebGLRenderer({ alpha: true, antialias: true, preserveDrawingBuffer: true });
  } catch (e) {
    return icons;
  }
  r.setSize(size, size, false);
  r.setPixelRatio(1);
  r.outputColorSpace = SRGBColorSpace;
  r.toneMapping = ACESFilmicToneMapping;
  r.toneMappingExposure = 1.35;
  const scene = new Scene();
  scene.add(new HemisphereLight("#ffffff", "#8a7a68", 2.3));
  const d = new DirectionalLight("#fff4e0", 3);
  d.position.set(2, 3, 2.5);
  scene.add(d);
  const fill = new DirectionalLight("#cfe8ff", 1.2);
  fill.position.set(-2, 0.5, 3);
  scene.add(fill);
  const cam = new PerspectiveCamera(30, 1, 0.01, 20);
  for (const id of Object.keys(ITEMS)) {
    const m = new Mesh(itemGeometry(id), itemMaterial);
    if (id === "leaf") m.rotation.set(1, 0.7, 0.2);
    else if (["stick", "wood", "fibre"].includes(id)) m.rotation.set(0.5, 0.6, 0.35);
    else if (["axe", "torch", "club", "obsidian_sword", "cutlass", "tusk_club", "torchpost", "shell_axe", "obsidian_axe", "iron_mace", "obsidian_knife", "machete", "stone_pick", "iron_pick", "iron_axe"].includes(id)) m.rotation.set(0.2, 0.5, -0.6);
    else if (["spear", "shell_spear", "obsidian_spear", "iron_spear", "rod"].includes(id)) m.rotation.set(0.2, 0.4, -0.85);
    else if (["ruby", "sapphire", "emerald", "amber"].includes(id)) m.rotation.set(0.3, 0.4, 0.2);
    else if (["shell", "shell_sea", "shell_water", "plot"].includes(id)) m.rotation.set(0.7, 0.6, 0);
    else m.rotation.set(0.45, 0.6, 0);
    scene.add(m);
    const box2 = new Box3().setFromObject(m);
    const sph = box2.getBoundingSphere(new Sphere());
    const dist = sph.radius / Math.sin(MathUtils.degToRad(15)) * 1.02;
    cam.position.set(sph.center.x, sph.center.y + dist * 0.25, sph.center.z + dist * 0.97);
    cam.lookAt(sph.center);
    r.render(scene, cam);
    icons[id] = r.domElement.toDataURL("image/png");
    scene.remove(m);
  }
  r.dispose();
  r.forceContextLoss?.();
  return icons;
}

