  const belly = new MeshStandardMaterial({ color: "#d9dde0", roughness: 0.7 });
  const body = new Mesh(new SphereGeometry(0.5, 14, 10).scale(0.75, 0.62, 3.2), skin);
  g.add(body);
  const under = new Mesh(new SphereGeometry(0.47, 12, 8, 0, Math.PI * 2, Math.PI * 0.55, Math.PI * 0.45).scale(0.74, 0.6, 3), belly);
  under.position.y = -0.02;
  g.add(under);
