  fin.moveTo(-0.45, 0);
  fin.quadraticCurveTo(-0.1, 0.35, 0.28, 0.9);
  fin.quadraticCurveTo(0.12, 0.4, 0.45, 0);
  fin.lineTo(-0.45, 0);
