  const dorsal = new Mesh(finGeo2, skin);
  dorsal.position.set(0, 0.22, 0.1);
  g.add(dorsal);
  const tail = new Group();
  tail.position.z = -1.5;
  g.add(tail);
  const tf = new Shape();
  tf.moveTo(0, 0);
  tf.lineTo(0.35, 0.75);
  tf.lineTo(0.15, 0.05);
  tf.lineTo(0.3, -0.45);
  tf.lineTo(0, 0);
  const tailFin = new Mesh(new ExtrudeGeometry(tf, { depth: 0.05, bevelEnabled: false }).translate(0, 0, -0.025).rotateY(Math.PI / 2), skin);
