var Sharks = class {
  constructor(scene, terrain) {
    this.terrain = terrain;
    this.mesh = buildShark();
    this.mesh.visible = false;
    scene.add(this.mesh);
    this.state = "away";
    this.t = 0;
    this.deepT = 0;
    this.ang = 0;
    this.r = 30;
    this.biteT = 0;
    this.pos = new Vector3();
    this.yaw = 0;
    this.depth = 0.35;
  }
  get near() {
    return this.state === "circle" || this.state === "attack";
  }
  // deep = swimming (not on a raft) where the sea floor is far below
  update(dt, time, player, { onBite, onWarn }) {
    const p = player.pos;
    const deep = player.swimming && !player.raft && this.terrain.heightAt(p.x, p.z) < -6;
    this.deepT = deep ? this.deepT + dt : Math.max(0, this.deepT - dt * 3);
    const m = this.mesh;
    if (this.state === "away") {
      if (deep && this.deepT > 7) {
        this.state = "circle";
        this.t = 0;
        this.r = 24;
        this.ang = Math.random() * Math.PI * 2;
        this.biteT = 0;
        this.pos.set(p.x + Math.cos(this.ang) * this.r, 0, p.z + Math.sin(this.ang) * this.r);
        m.visible = true;
        onWarn?.();
      }
      return;
    }
    this.t += dt;
    let tx, tz, speed = 5;
    if (this.state === "leave") {
      const ax = this.pos.x - p.x, az = this.pos.z - p.z, L2 = Math.hypot(ax, az) || 1;
      tx = this.pos.x + ax / L2 * 10;
      tz = this.pos.z + az / L2 * 10;
      speed = 6;
      this.depth = damp5(this.depth, 1.6, 0.8, dt);
      if (this.t > 6) {
        this.state = "away";
        m.visible = false;
        this.depth = 0.35;
        return;
      }
    } else {
      if (!deep) {
        this.state = "leave";
        this.t = 0;
      }
      this.depth = damp5(this.depth, 0.35, 2, dt);
      if (this.state === "circle") {
        this.r = Math.max(4, this.r - dt * 1.4);
        this.ang += dt * 4.5 / this.r;
        tx = p.x + Math.cos(this.ang) * this.r;
        tz = p.z + Math.sin(this.ang) * this.r;
        this.biteT -= dt;
        if (this.r <= 4.5 && this.t > 13 && this.biteT <= 0) {
          this.state = "attack";
        }
      } else {
        tx = p.x;
        tz = p.z;
        speed = 8;
        if (Math.hypot(this.pos.x - p.x, this.pos.z - p.z) < 1.6) {
          onBite?.(12, this.pos);
          this.state = "circle";
          this.r = 9;
          this.biteT = 4.5;
          this.ang = Math.atan2(this.pos.z - p.z, this.pos.x - p.x) + 0.5;
        }
      }
    }
    const want = Math.atan2(tx - this.pos.x, tz - this.pos.z);
    this.yaw += angleTo3(this.yaw, want) * (1 - Math.exp(-(this.state === "attack" ? 6 : 3) * dt));
    this.pos.x += Math.sin(this.yaw) * speed * dt;
    this.pos.z += Math.cos(this.yaw) * speed * dt;
    if (this.terrain.heightAt(this.pos.x, this.pos.z) > -2) {
      this.pos.x -= Math.sin(this.yaw) * speed * dt * 2;
      this.pos.z -= Math.cos(this.yaw) * speed * dt * 2;
      this.ang += 0.6;
    }
    m.position.set(this.pos.x, -this.depth + Math.sin(time * 2.3) * 0.05, this.pos.z);
    m.rotation.set(0, this.yaw, Math.sin(time * 1.7) * 0.05);
    m.userData.tail.rotation.y = Math.sin(time * (this.state === "attack" ? 11 : 6)) * 0.35;
  }
  reset() {
    this.state = "away";
    this.mesh.visible = false;
    this.deepT = 0;
  }
};

