          r.regrowDay = this.day + 3;
          this.setWildMatrix(r);
          this.emit("wild", { idx: r.idx, regrowDay: r.regrowDay });
          this.fx?.burst(_v3.set(r.x, r.h + 0.15, r.z), "#6b4a30", 14, 1.6, { up: 2, size: 0.06 });
