    if (isDogFood(sel?.id)) return dog.food >= 90 ? { e: `${dog.name}\u2019s full`, eOff: true, use: null } : { e: `Feed ${dog.name}`, use: null };
    if (sel?.id === "shell_water") return dog.water >= 90 ? { e: `${dog.name} isn\u2019t thirsty`, eOff: true, use: null } : { e: `Give ${dog.name} a drink`, use: null };
    const m = dog.mood;
