  function giveHaul(m, items) {
    const b = crew.bedOf(m);
    if (!b) return;
    const chest2 = world.structures.filter((s) => s.type === "storage" && Math.hypot(s.x - b.x, s.z - b.z) < 25).sort((a, c) => Math.hypot(a.x - b.x, a.z - b.z) - Math.hypot(c.x - b.x, c.z - b.z))[0];
    const got = [];
    let spilled = false;
    for (const [id, n] of items) {
      let left = n;
      if (chest2) {
        const max = ITEMS[id].stack || 1;
        for (const t2 of chest2.items) {
          if (left <= 0) break;
          if (t2 && t2.id === id && t2.n < max) {
            const k = Math.min(max - t2.n, left);
            t2.n += k;
            left -= k;
          }
        }
        for (let k = 0; k < chest2.items.length && left > 0; k++) if (!chest2.items[k]) {
          chest2.items[k] = { id, n: Math.min(max, left) };
          left -= chest2.items[k].n;
        }
      }
      for (let k = 0; k < left; k++) {
        world.spawnDrop(id, b.x + 0.9 + Math.random() * 0.6, b.z + (Math.random() - 0.5) * 0.8);
        spilled = true;
      }
      got.push(`${n} ${ITEMS[id].name.toLowerCase()}`);
    }
    if (chest2) {
      world.emit("box", { sid: chest2.sid, items: chest2.items });
      world.onBoxChange?.(chest2);
    }
    const list = got.length > 1 ? got.slice(0, -1).join(", ") + " and " + got.at(-1) : got[0];
    m.news = `Brought you ${list} today. ${chest2 && !spilled ? "It\u2019s in the chest." : "It\u2019s by my bed. Build a storage chest near it and I\u2019ll use that."}`;
    if (Math.hypot(player.pos.x - b.x, player.pos.z - b.z) < 90) ui.toast(`${m.d.name} brought back ${list}`);
    saveGame();
  }
